-- MySQL 8 production schema. The local development adapter mirrors these entities.
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(150) NOT NULL UNIQUE, phone VARCHAR(20) UNIQUE, password_hash VARCHAR(255) NOT NULL, avatar_url VARCHAR(255), is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE messes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(150) NOT NULL, address VARCHAR(255), currency VARCHAR(10) NOT NULL DEFAULT 'BDT', created_by BIGINT UNSIGNED NOT NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE mess_members (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, mess_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, role ENUM('manager','member') NOT NULL DEFAULT 'member', joined_at DATE NOT NULL, left_at DATE, status ENUM('active','inactive') NOT NULL DEFAULT 'active', UNIQUE KEY uniq_mess_user(mess_id,user_id), FOREIGN KEY(mess_id) REFERENCES messes(id) ON DELETE CASCADE, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE mess_cycles (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, mess_id BIGINT UNSIGNED NOT NULL, cycle_year SMALLINT NOT NULL, cycle_month TINYINT NOT NULL, status ENUM('open','closed') NOT NULL DEFAULT 'open', total_bazar_amount DECIMAL(12,2) DEFAULT 0, total_other_cost DECIMAL(12,2) DEFAULT 0, total_meals DECIMAL(10,2) DEFAULT 0, meal_rate DECIMAL(10,4) DEFAULT 0, closed_at DATETIME, closed_by BIGINT UNSIGNED, UNIQUE KEY uniq_mess_month(mess_id,cycle_year,cycle_month), FOREIGN KEY(mess_id) REFERENCES messes(id) ON DELETE CASCADE, FOREIGN KEY(closed_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE cycle_member_status (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, cycle_id BIGINT UNSIGNED NOT NULL, mess_member_id BIGINT UNSIGNED NOT NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE, opening_due DECIMAL(12,2) NOT NULL DEFAULT 0, note VARCHAR(255), UNIQUE KEY uniq_cycle_member(cycle_id,mess_member_id), FOREIGN KEY(cycle_id) REFERENCES mess_cycles(id) ON DELETE CASCADE, FOREIGN KEY(mess_member_id) REFERENCES mess_members(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE meals (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, cycle_id BIGINT UNSIGNED NOT NULL, mess_member_id BIGINT UNSIGNED NOT NULL, meal_date DATE NOT NULL, breakfast DECIMAL(4,2) NOT NULL DEFAULT 0, lunch DECIMAL(4,2) NOT NULL DEFAULT 0, dinner DECIMAL(4,2) NOT NULL DEFAULT 0, guest_meals DECIMAL(4,2) NOT NULL DEFAULT 0, UNIQUE KEY uniq_meal(cycle_id,mess_member_id,meal_date), FOREIGN KEY(cycle_id) REFERENCES mess_cycles(id) ON DELETE CASCADE, FOREIGN KEY(mess_member_id) REFERENCES mess_members(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE bazar_entries (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, cycle_id BIGINT UNSIGNED NOT NULL, mess_member_id BIGINT UNSIGNED NOT NULL, bazar_date DATE NOT NULL, total_amount DECIMAL(12,2) NOT NULL DEFAULT 0, note VARCHAR(255), receipt_image_url VARCHAR(255), FOREIGN KEY(cycle_id) REFERENCES mess_cycles(id) ON DELETE CASCADE, FOREIGN KEY(mess_member_id) REFERENCES mess_members(id)) ENGINE=InnoDB;
CREATE TABLE bazar_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, bazar_entry_id BIGINT UNSIGNED NOT NULL, product_name VARCHAR(100) NOT NULL, quantity DECIMAL(10,3) NOT NULL, unit VARCHAR(20), unit_price DECIMAL(10,2) NOT NULL, sub_total DECIMAL(12,2) NOT NULL, FOREIGN KEY(bazar_entry_id) REFERENCES bazar_entries(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE deposits (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, cycle_id BIGINT UNSIGNED NOT NULL, mess_member_id BIGINT UNSIGNED NOT NULL, amount DECIMAL(12,2) NOT NULL, deposit_date DATE NOT NULL, payment_method ENUM('cash','bkash','nagad','bank','other') NOT NULL, received_by BIGINT UNSIGNED, FOREIGN KEY(cycle_id) REFERENCES mess_cycles(id) ON DELETE CASCADE, FOREIGN KEY(mess_member_id) REFERENCES mess_members(id), FOREIGN KEY(received_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE other_costs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, cycle_id BIGINT UNSIGNED NOT NULL, category ENUM('utility','rent','servant','maintenance','other') NOT NULL, title VARCHAR(150) NOT NULL, amount DECIMAL(12,2) NOT NULL, cost_date DATE NOT NULL, split_type ENUM('equal','meal_based') NOT NULL, FOREIGN KEY(cycle_id) REFERENCES mess_cycles(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE member_month_summary (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, cycle_id BIGINT UNSIGNED NOT NULL, mess_member_id BIGINT UNSIGNED NOT NULL, total_meals DECIMAL(10,2) NOT NULL, meal_cost DECIMAL(12,2) NOT NULL, other_cost_share DECIMAL(12,2) NOT NULL, total_cost DECIMAL(12,2) NOT NULL, total_deposit DECIMAL(12,2) NOT NULL, opening_due DECIMAL(12,2) NOT NULL, balance DECIMAL(12,2) NOT NULL, status ENUM('due','refund','settled') NOT NULL, UNIQUE KEY uniq_summary(cycle_id,mess_member_id), FOREIGN KEY(cycle_id) REFERENCES mess_cycles(id) ON DELETE CASCADE, FOREIGN KEY(mess_member_id) REFERENCES mess_members(id)) ENGINE=InnoDB;
CREATE TABLE activity_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, mess_id BIGINT UNSIGNED, user_id BIGINT UNSIGNED, action VARCHAR(100) NOT NULL, entity_type VARCHAR(50), entity_id BIGINT UNSIGNED, meta JSON, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
